local SettingRefBase = require('Game.Setting.SettingRefBase')
local base = SettingRefBase

---@class GuideBookTabVo
local GuideBookTabVo = Class("GuideBookTabVo", SettingRefBase)

function GuideBookTabVo:__init()
    self:CleanField()
end

function GuideBookTabVo:__delete()
   self:CleanField()
end

function GuideBookTabVo:CleanField()
    self.indexTab = nil
    self.strTitle = nil
    self.arrTabDesc = nil
    self.ifLoop = nil
end

---FillVo
---@param row TableML.TableFileRow
function GuideBookTabVo:FillVo(row)
    base.FillVo(self, row)
    --- 页签编号
    self.indexTab = parse_number(row, "tab")
    --- 页签标题
    self.strTitle = parse_localizeText(row, "title")
    --- 页签描述
    local confDataDesc = parse_localizeText(row, "text")
    local strArrConfDesc = string.split(confDataDesc, ";")
    for i = 1, #strArrConfDesc do
        strArrConfDesc[i] = string.gsub(strArrConfDesc[i], "/n", "\n")
        strArrConfDesc[i] = string.gsub(strArrConfDesc[i], "\\n", "\n")
    end
    self.arrTabDesc = strArrConfDesc
    self.ifLoop = parse_number(row, "ifLoop") --界面动画是否循环
end

return GuideBookTabVo